#!/usr/bin/env bash\n# Test that the Terraform module defines required resources and settings.\n\nset -euo pipefail\n\nMODULE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"\n\n# Helper to assert a pattern exists in a file\nassert_in_file() {\n  local pattern=$1\n  local file=$2\n  if ! grep -qE "$pattern" "$file"; then\n    echo "FAIL: Expected pattern '$pattern' not found in $file"\n    exit 1\n  fi\n}\n\n# Check main.tf for aws_s3_bucket resource\nassert_in_file "resource \"aws_s3_bucket\" \"safehouse\"" "$MODULE_DIR/main.tf"\n\n# Check versioning enabled\nassert_in_file "versioning \{[^}]*enabled = true" "$MODULE_DIR/main.tf"\n\n# Check server-side encryption\nassert_in_file "sse_algorithm = \"AES256\"" "$MODULE_DIR/main.tf"\n\n# Check public access blocks\nassert_in_file "block_public_acls\\s*=\\s*true" "$MODULE_DIR/main.tf"\n\n# Check lifecycle rule for Glacier transition\nassert_in_file "storage_class = \"GLACIER\"" "$MODULE_DIR/main.tf"\n\necho "All checks passed."\n
